/**
* Calculates Euclidean distance in meters from a point to a line segment in WGS84.
*/
function pointToSegmentDistanceMeters(p, a, b) {
	const latM = 110574;
	const lngM = 103780;
	const px = p[0] * lngM;
	const py = p[1] * latM;
	const ax = a[0] * lngM;
	const ay = a[1] * latM;
	const bx = b[0] * lngM;
	const by = b[1] * latM;
	const dx = bx - ax;
	const dy = by - ay;
	const lenSq = dx * dx + dy * dy;
	if (lenSq === 0) return Math.hypot(px - ax, py - ay);
	let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
	t = Math.max(0, Math.min(1, t));
	const projX = ax + t * dx;
	const projY = ay + t * dy;
	return Math.hypot(px - projX, py - projY);
}
